    match = re.match(r"^(?P<name>[a-zA-Z0-9\-_]+)(?:\s*$(?P<version>[^$]+)$)?$", requirement)
    if not match:
        raise ValueError(f"Invalid requirement format: {requirement}")

    name = match.group("name")
    version = match.group("version") or ""

    return {"name": name, "version": version}


