import os
import sys

from oneagent import OneAgent

class AutoInstrument:
    def __init__(self):
        self.oneagent = OneAgent()
        self.loaded_modules = set()

    def load_module(self, module_path):
        if module_path in self.loaded_modules:
            return

        module = importlib.import_module(module_path)
        self.loaded_modules.add(module_path)

        for name, obj in inspect.getmembers(module):
            if inspect.isclass(obj) and hasattr(obj, "__init__"):
                self._instrument_class(obj)

    def _instrument_class(self, cls):
        for name, method in inspect.getmembers(cls, predicate=inspect.isfunction):
            if name != "__init__":
                setattr(cls, name, self.oneagent.instrument(method))

    def instrument_all(self):
        for module in sys.modules.values():
            if module.__file__ and module.__file__.endswith(".py"):
                module_path = os.path.splitext(module.__file__)[0]
                self.load_module(module_path)

