def generate_qr_code(data, file_name, color, size, qr_type):
    if qr_type == "qr":
        qr = qrcode.QRCode(version=1, box_size=size, border=4)
    elif qr_type == "micro_qr":
        qr = qrcode.QRCode(version=1, box_size=size, border=4, mode='alphanumeric')
    else:
        raise ValueError("Invalid QR code type. Use 'qr' or 'micro_qr'.")
