from bs4 import BeautifulSoup
import re

def parse_html(html):
    soup = BeautifulSoup(html, "html.parser")
    h_cards = soup.find_all("div", class_=re.compile(r"^(h-|h-\d+|h-\d+-\d+)-"))
    parsed_data = []

    for card in h_cards:
        card_type = card.get("class")[0].split("-")[1]
        card_data = {"type": card_type}
        for key in card.attrs:
            if key not in ["class", "id", "style"]:
                card_data[key] = card.get(key)
        for child in card.children:
            if child.name:
                card_data[child.name] = child.text
        parsed_data.append(card_data)

    return parsed_data

