import dash
from dash import Dash, html, dcc, callback, Output, Input, State
import dash_mantine_components as dmc
import plotly.express as px
import pandas as pd

# Load data
df = pd.read_csv('data.csv')

app = Dash(__name__)
app.layout = html.Div([
    dmc.Grid(
        children=[
            dmc.Col(
                dmc.Card(
                    children=[
                        dmc.Group(
                            [
                                dmc.TextInput(id='filter-text', label='Text Filter', placeholder='Enter text to filter'),
                                dmc.Select(id='filter-select', label='Select Filter', data=[{'label': 'All', 'value': 'all'}] + [{'label': col, 'value': col} for col in df.columns]),
                                dmc.Button('Apply', id='apply-button', variant='outline')
                            ],
                            spacing='md'
                        ),
                        dmc.Group(
                            [
                                dmc.Switch(id='dark-mode-toggle', label='Dark Mode', checked=False),
                                dmc.Slider(id='opacity-slider', label='Opacity', min=0, max=100, value=50)
                            ],
                            spacing='md'
                        ),
                        dmc.Space(h='md'),
                        dmc.Group(
                            [
                                dmc.Button('Reset', id='reset-button', variant='outline'),
                                dmc.Button('Download', id='download-button', variant='outline')
                            ],
                            spacing='md'
                        )
                    ],
                    withBorder=True,
                    radius='md',
                    p='md'
                ),
                span=3
            ),
            dmc.Col(
                dmc.Card(
                    children=[
                        dmc.Group(
                            [
                                dmc.Select(id='chart-type-select', label='Chart Type', data=[{'label': 'Bar', 'value': 'bar'}, {'label': 'Line', 'value': 'line'}, {'label': 'Scatter', 'value': 'scatter'}]),
                                dmc.Select(id='x-axis-select', label='X-Axis', data=[{'label': col, 'value': col} for col in df.columns]),
                                dmc.Select(id='y-axis-select', label='Y-Axis', data=[{'label': col, 'value': col} for col in df.columns]),
                                dmc.Button('Update Chart', id='update-chart-button', variant='outline')
                            ],
                            spacing='md'
                        ),
                        dcc.Graph(id='chart')
                    ],
                    withBorder=True,
                    radius='md',
                    p='md'
                ),
                span=9
            )
        ],
        gutter='md'
    )
])

@callback(
    Output('chart', 'figure'),
    Input('update-chart-button', 'n_clicks'),
    Input('chart-type-select', 'value'),
    Input('x-axis-select', 'value'),
    Input('y-axis-select', 'value'),
    Input('dark-mode-toggle', 'checked'),
    Input('opacity-slider', 'value'),
    Input('filter-text', 'value'),
    Input('filter-select', 'value'),
    State('chart', 'figure')
)
def update_chart(n_clicks, chart_type, x_axis, y_axis, dark_mode, opacity, filter_text, filter_select, figure):
    if n_clicks is None:
        return figure

    filtered_df = df.copy()
    if filter_text:
        filtered_df = filtered_df[filtered_df.apply(lambda row: filter_text in row.values.astype(str), axis=1)]
    if filter_select != 'all':
        filtered_df = filtered_df[filtered_df[filter_select] == filter_select]

    if chart_type == 'bar':
        fig = px.bar(filtered_df, x=x_axis, y=y_axis, opacity=opacity/100)
    elif chart_type == 'line':
        fig = px.line(filtered_df, x=x_axis, y=y_axis, opacity=opacity/100)
    elif chart_type == 'scatter':
        fig = px.scatter(filtered_df, x=x_axis, y=y_axis, opacity=opacity/100)
    else:
        fig = px.scatter(filtered_df, x=x_axis, y=y_axis, opacity=opacity/100)

    fig.update_layout(darkmode=dark_mode)
    return fig

@callback(
    Output('filter-select', 'data'),
    Input('filter-text', 'value'),
    Input('filter-select', 'value'),
    State('filter-select', 'data')
)
def update_filter_options(filter_text, selected_value, data):
    if filter_text:
        filtered_data = [option for option in data if filter_text in option['label']]
    else:
        filtered_data = data
    return filtered_data

@callback(
    Output('x-axis-select', 'data'),
    Input('x-axis-select', 'value'),
    State('x-axis-select', 'data')
)
def update_x_axis_options(selected_value, data):
    if selected_value:
        filtered_data = [option for option in data if selected_value in option['label']]
    else:
        filtered_data = data
    return filtered_data

@callback(
    Output('y-axis-select', 'data'),
    Input('y-axis-select', 'value'),
    State('y-axis-select', 'data')
)
def update_y_axis_options(selected_value, data):
    if selected_value:
        filtered_data = [option for option in data if selected_value in option['label']]
    else:
        filtered_data = data
    return filtered_data

if __name__ == '__main__':
    app.run(debug=True)
