from dash import Dash, html, dcc
import dash_mantine_components as dmc
import pandas as pd
import numpy as np

# Create a sample DataFrame
df = pd.DataFrame({
    'x': np.random.rand(100),
    'y': np.random.rand(100)
})

# Initialize the Dash app
app = Dash(__name__)
app.title = "Interactive Dashboard"

# Define the layout of the dashboard
app.layout = dmc.MantineProvider(
    children=[
        dmc.Container([
            dmc.Title("Interactive Dashboard", order=1, mt=20),
            dmc.Text("Explore and visualize data insights with ease.", mt=10, mb=20),
            dmc.Group([
                dmc.TextInput(id='x-axis-input', label='X-axis', placeholder='Enter x-axis column name'),
                dmc.TextInput(id='y-axis-input', label='Y-axis', placeholder='Enter y-axis column name'),
                dmc.Button('Plot', id='plot-button', mt=10)
            ], justify='center', mb=20),
            dcc.Graph(id='scatter-plot', figure={})
        ], size="xl")
    ]
)

# Define the callback to update the scatter plot
@app.callback(
    Output('scatter-plot', 'figure'),
    [Input('plot-button', 'n_clicks')],
    [State('x-axis-input', 'value'),
     State('y-axis-input', 'value')]
)
def update_plot(n_clicks, x_col, y_col):
    if n_clicks is None:
        return {}

    if x_col not in df.columns or y_col not in df.columns:
        return {}

    fig = px.scatter(df, x=x_col, y=y_col)
    return fig

# Run the app
if __name__ == '__main__':
    app.run_server(debug=True)
